<script setup lang="ts">
import { computed } from 'vue'; import type { ProviderProfile } from '../api/system'; import { useI18nStore } from '../stores/i18n';
const props=defineProps<{modelValue:string;profiles:ProviderProfile[];disabled?:boolean;task?:string}>(); const emit=defineEmits<{"update:modelValue":[value:string]}>(); const i18n=useI18nStore(); const selected=computed(()=>props.profiles.find(p=>p.id===props.modelValue)||null);
</script><template><section class="llm-execution" role="group" :aria-label="i18n.t('pdf_corpus.llm_execution','LLM execution')"><div class="llm-notice"><span aria-hidden="true">AI</span><div><b>{{i18n.t('pdf_corpus.llm_will_be_used','This action uses an LLM')}}</b><small>{{task||i18n.t('pdf_corpus.llm_choose_profile_help','Choose the provider profile that should perform this action.')}}</small></div></div><label><span>{{i18n.t('pdf_corpus.provider_profile','Provider profile')}}</span><select class="control" :value="modelValue" :disabled="disabled||!profiles.length" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="" disabled>{{i18n.t('pdf_corpus.choose_provider_profile','Choose a provider profile…')}}</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{profile.name||profile.id}} · {{profile.model||i18n.t('pdf_corpus.model_not_set','model not set')}}</option></select></label><small v-if="selected" class="selected-model">{{i18n.tf('pdf_corpus.llm_selected_model','Selected model: {model}',{model:selected.model||i18n.t('pdf_corpus.model_not_set','model not set')})}}</small></section></template><style scoped>.llm-execution{display:grid;grid-template-columns:minmax(220px,1fr) minmax(260px,1fr);gap:10px 14px;align-items:end;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--soft)}.llm-notice{display:flex;gap:9px;align-items:flex-start}.llm-notice>span{display:grid;place-items:center;min-width:32px;height:32px;border-radius:8px;background:var(--text);color:var(--card);font-size:.75rem;font-weight:850}.llm-notice div,.llm-execution label{display:grid;gap:3px}.llm-notice b,.llm-execution label>span{font-size:.8125rem}.llm-notice small,.selected-model{font-size:.8125rem;color:var(--muted);line-height:1.35}.control{min-height:42px}.selected-model{grid-column:2}.control:focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:720px){.llm-execution{grid-